package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
)

const tasksFile = "tasks.json"

// Task represents a single todo item
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// readTasks reads tasks from the tasks.json file
func readTasks() ([]Task, error) {
	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			return []Task{}, nil // Return empty slice if file doesn't exist
		}
		return nil, fmt.Errorf("error reading tasks file: %w", err)
	}

	var tasks []Task
	if err := json.Unmarshal(data, &tasks); err != nil {
		return nil, fmt.Errorf("error unmarshalling tasks: %w", err)
	}
	return tasks, nil
}

// saveTasks writes tasks to the tasks.json file
func saveTasks(tasks []Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("error marshalling tasks: %w", err)
	}
	if err := ioutil.WriteFile(tasksFile, data, 0644); err != nil {
		return fmt.Errorf("error writing tasks file: %w", err)
	}
	return nil
}

func printErrorAndExit(err string, code int) {
	output := map[string]string{"error": err}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
	os.Exit(code)
}

func main() {
	if len(os.Args) < 2 {
		printErrorAndExit("invalid arguments", 42)
	}

	command := os.Args[1]

	switch command {
	case "add":
		if len(os.Args) < 3 {
			printErrorAndExit("invalid arguments", 42)
		}
		description := os.Args[2]
		addTask(description)
	case "list":
		listTasks()
	case "done":
		if len(os.Args) < 3 {
			printErrorAndExit("invalid arguments", 42)
		}
		idStr := os.Args[2]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			printErrorAndExit("invalid arguments: task ID must be an integer", 42)
		}
		completeTask(id)
	default:
		printErrorAndExit(fmt.Sprintf("unknown command: %s", command), 42)
	}
}

func addTask(description string) {
	tasks, err := readTasks()
	if err != nil {
		printErrorAndExit(err.Error(), 1)
	}

	nextID := 1
	if len(tasks) > 0 {
		nextID = tasks[len(tasks)-1].ID + 1
	}

	newTask := Task{
		ID:          nextID,
		Description: description,
		Done:        false,
	}
	tasks = append(tasks, newTask)

	if err := saveTasks(tasks); err != nil {
		printErrorAndExit(err.Error(), 1)
	}

	output := map[string]interface{}{"id": newTask.ID, "status": "added"}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
}

func listTasks() {
	tasks, err := readTasks()
	if err != nil {
		printErrorAndExit(err.Error(), 1)
	}

	var pendingTasks []Task
	for _, task := range tasks {
		if !task.Done {
			pendingTasks = append(pendingTasks, task)
		}
	}

	jsonOutput, _ := json.Marshal(pendingTasks)
	fmt.Println(string(jsonOutput))
}

func completeTask(id int) {
	tasks, err := readTasks()
	if err != nil {
		printErrorAndExit(err.Error(), 1)
	}

	found := false
	for i := range tasks {
		if tasks[i].ID == id {
			tasks[i].Done = true
			found = true
			break
		}
	}

	if !found {
		printErrorAndExit(fmt.Sprintf("task with ID %d not found", id), 42)
	}

	if err := saveTasks(tasks); err != nil {
		printErrorAndExit(err.Error(), 1)
	}

	output := map[string]interface{}{"id": id, "status": "completed"}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
}

package main

import (
	"encoding/json"
	"io/ioutil"
	"os"
	"path/filepath"
	"testing"
)

func TestMain(m *testing.M) {
	// Create a temporary directory for test files
	testDir, err := ioutil.TempDir("", "todo_test_")
	if err != nil {
		panic(err)
	}

	// Change to the temporary directory
	oldCwd, err := os.Getwd()
	if err != nil {
		panic(err)
	}

	if err := os.Chdir(testDir);
		err != nil {
		panic(err)
	}

	// Run tests
	code := m.Run()

	// Clean up: change back to original directory and remove temporary directory
	if err := os.Chdir(oldCwd);
		err != nil {
		panic(err)
	}

	if err := os.RemoveAll(testDir);
		err != nil {
		panic(err)
	}

	os.Exit(code)
}

func TestAddTask(t *testing.T) {
	// Clear tasks.json before test
	if err := os.Remove(tasksFile);
		err != nil && !os.IsNotExist(err) {
		t.Fatalf("failed to remove %s: %v", tasksFile, err)
	}

	description := "Test Task 1"
	addTask(description)

	tasks, err := readTasks()
	if err != nil {
		t.Fatalf("failed to read tasks: %v", err)
	}

	if len(tasks) != 1 {
		t.Fatalf("expected 1 task, got %d", len(tasks))
	}

	if tasks[0].Description != description || tasks[0].ID != 1 || tasks[0].Done != false {
		t.Errorf("unexpected task content: %+v", tasks[0])
	}

	description2 := "Test Task 2"
	addTask(description2)

	tasks, err = readTasks()
	if err != nil {
		t.Fatalf("failed to read tasks: %v", err)
	}

	if len(tasks) != 2 {
		t.Fatalf("expected 2 tasks, got %d", len(tasks))
	}

	if tasks[1].Description != description2 || tasks[1].ID != 2 || tasks[1].Done != false {
		t.Errorf("unexpected task content: %+v", tasks[1])
	}
}

func TestListTasks(t *testing.T) {
	// Clear tasks.json before test
	if err := os.Remove(tasksFile);
		err != nil && !os.IsNotExist(err) {
		t.Fatalf("failed to remove %s: %v", tasksFile, err)
	}

	addTask("Task for listing 1")
	addTask("Task for listing 2")

	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	listTasks()

	w.Close()
	os.Stdout = oldStdout
	out, _ := ioutil.ReadAll(r)

	var listedTasks []Task
	if err := json.Unmarshal(out, &listedTasks); err != nil {
		t.Fatalf("failed to unmarshal list output: %v", err)
	}

	if len(listedTasks) != 2 {
		t.Fatalf("expected 2 listed tasks, got %d", len(listedTasks))
	}

	if listedTasks[0].Description != "Task for listing 1" || listedTasks[1].Description != "Task for listing 2" {
		t.Errorf("unexpected listed tasks: %+v", listedTasks)
	}
}

func TestCompleteTask(t *testing.T) {
	// Clear tasks.json before test
	if err := os.Remove(tasksFile);
		err != nil && !os.IsNotExist(err) {
		t.Fatalf("failed to remove %s: %v", tasksFile, err)
	}

	addTask("Task to complete")
	addTask("Another task")

	completeTask(1)

	tasks, err := readTasks()
	if err != nil {
		t.Fatalf("failed to read tasks: %v", err)
	}

	if len(tasks) != 2 {
		t.Fatalf("expected 2 tasks after completion, got %d", len(tasks))
	}

	if !tasks[0].Done {
		t.Errorf("task 1 should be done, but is not: %+v", tasks[0])
	}

	if tasks[1].Done {
		t.Errorf("task 2 should not be done, but is: %+v", tasks[1])
	}

	// Test completing a non-existent task
	oldStderr := os.Stderr
	r, w, _ := os.Pipe()
	os.Stderr = w

	oldExit := exit
	exit = func(code int) {
		if code != 42 {
			t.Errorf("expected exit code 42, got %d", code)
		}
		panic("exit called") // Panic to stop execution in test
	}

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected exit to be called for non-existent task")
		}
		w.Close()
		os.Stderr = oldStderr
		exit = oldExit
	}()

	completeTask(99)
}

// Override os.Exit for testing purposes
var exit = os.Exit

func init() {
	os.Exit = func(code int) {
		panic("os.Exit called with code " + strconv.Itoa(code)) // During tests, panic instead of exit
	}
}

