package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// mockExit is a mock function for os.Exit to prevent actual program termination during tests.
var mockExitCode int
var mockExitCalled bool

func mockExit(code int) {
	mockExitCode = code
	mockExitCalled = true
	panic("exit called") // Panic to stop execution in test
}

func TestMain(m *testing.M) {
	// Create a temporary directory for test files
	testDir, err := ioutil.TempDir("", "todo_test_")
	if err != nil {
		panic(err)
	}

	// Store the original tasksFile path
	originalTasksFile := tasksFile

	// Set tasksFile to a path within the temporary directory
	tasksFile = filepath.Join(testDir, "tasks.json")

	// Run tests
	code := m.Run()

	// Clean up: restore original tasksFile and remove temporary directory
	tasksFile = originalTasksFile
	if err := os.RemoveAll(testDir);
		err != nil {
		fmt.Printf("Error cleaning up test directory %s: %v\n", testDir, err)
	}

	os.Exit(code)
}

func TestAddTask(t *testing.T) {
	// Clear tasks.json before test
	if err := os.Remove(tasksFile);
		err != nil && !os.IsNotExist(err) {
		t.Fatalf("failed to remove %s: %v", tasksFile, err)
	}

	description := "Test Task 1"
	addTask(description, mockExit)

	tasks, err := readTasks()
	if err != nil {
		t.Fatalf("failed to read tasks: %v", err)
	}

	if len(tasks) != 1 {
		t.Fatalf("expected 1 task, got %d", len(tasks))
	}

	if tasks[0].Description != description || tasks[0].ID != 1 || tasks[0].Done != false {
		t.Errorf("unexpected task content: %+v", tasks[0])
	}

	description2 := "Test Task 2"
	addTask(description2, mockExit)

	tasks, err = readTasks()
	if err != nil {
		t.Fatalf("failed to read tasks: %v", err)
	}

	if len(tasks) != 2 {
		t.Fatalf("expected 2 tasks, got %d", len(tasks))
	}

	if tasks[1].Description != description2 || tasks[1].ID != 2 || tasks[1].Done != false {
		t.Errorf("unexpected task content: %+v", tasks[1])
	}
}

func TestListTasks(t *testing.T) {
	// Clear tasks.json before test
	if err := os.Remove(tasksFile);
		err != nil && !os.IsNotExist(err) {
		t.Fatalf("failed to remove %s: %v", tasksFile, err)
	}

	addTask("Task for listing 1", mockExit)
	addTask("Task for listing 2", mockExit)

	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	listTasks(mockExit)

	w.Close()
	os.Stdout = oldStdout
	out, _ := ioutil.ReadAll(r)

	var listedTasks []Task
	if err := json.Unmarshal(out, &listedTasks); err != nil {
		t.Fatalf("failed to unmarshal list output: %v", err)
	}

	if len(listedTasks) != 2 {
		t.Fatalf("expected 2 listed tasks, got %d", len(listedTasks))
	}

	if listedTasks[0].Description != "Task for listing 1" || listedTasks[1].Description != "Task for listing 2" {
		t.Errorf("unexpected listed tasks: %+v", listedTasks)
	}
}

func TestCompleteTask(t *testing.T) {
	// Clear tasks.json before test
	if err := os.Remove(tasksFile);
		err != nil && !os.IsNotExist(err) {
		t.Fatalf("failed to remove %s: %v", tasksFile, err)
	}

	addTask("Task to complete", mockExit)
	addTask("Another task", mockExit)

	completeTask(1, mockExit)

	tasks, err := readTasks()
	if err != nil {
		t.Fatalf("failed to read tasks: %v", err)
	}

	if len(tasks) != 2 {
		t.Fatalf("expected 2 tasks after completion, got %d", len(tasks))
	}

	if !tasks[0].Done {
		t.Errorf("task 1 should be done, but is not: %+v", tasks[0])
	}

	if tasks[1].Done {
		t.Errorf("task 2 should not be done, but is: %+v", tasks[1])
	}

	// Test completing a non-existent task
	mockExitCalled = false
	mockExitCode = 0

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called")
		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		// Restore mockExitCalled and mockExitCode for subsequent tests
		mockExitCalled = false
		mockExitCode = 0
	}()

	completeTask(99, mockExit)
}

func TestMainFunction(t *testing.T) {
	// Test add command
	oldArgs := os.Args
	oldStdout := os.Stdout

	r, w, _ := os.Pipe()
	os.Stdout = w

	os.Args = []string{"todo", "add", "Test Main Task"}

	mockExitCalled = false
	defer func() {
		r := recover()
		if r != nil && r.(string) == "exit called" {
			// This is expected if main calls mockExit
		}
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs

		// Clear tasks.json after test
		if err := os.Remove(tasksFile);
			err != nil && !os.IsNotExist(err) {
			t.Fatalf("failed to remove %s: %v", tasksFile, err)
		}
	}()
	main()

	out, _ := ioutil.ReadAll(r)

	expected := `{"id":1,"status":"added"}`
	if strings.TrimSpace(string(out)) != expected {
		t.Errorf("expected %s, got %s", expected, strings.TrimSpace(string(out)))
	}

	// Test list command
	os.Args = []string{"todo", "list"}
	mockExitCalled = false
	r, w, _ = os.Pipe()
	os.Stdout = w

	defer func() {
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	main()
	out, _ = ioutil.ReadAll(r)

	expectedList := `[{"id":1,"description":"Test Main Task","done":false}]`
	if strings.TrimSpace(string(out)) != expectedList {
		t.Errorf("expected %s, got %s", expectedList, strings.TrimSpace(string(out)))
	}

	// Test done command
	os.Args = []string{"todo", "done", "1"}
	mockExitCalled = false
	r, w, _ = os.Pipe()
	os.Stdout = w

	defer func() {
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	main()
	out, _ = ioutil.ReadAll(r)

	expectedDone := `{"id":1,"status":"completed"}`
	if strings.TrimSpace(string(out)) != expectedDone {
		t.Errorf("expected %s, got %s", expectedDone, strings.TrimSpace(string(out)))
	}

	// Test invalid command
	os.Args = []string{"todo", "invalid"}
	mockExitCalled = false
	mockExitCode = 0
	r, w, _ = os.Pipe()
	os.Stderr = w // Error output for invalid command

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called for invalid command")
		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		w.Close()
		os.Stderr = oldStderr
		os.Args = oldArgs
	}()
	main()
}

func TestMainFunctionInvalidArgs(t *testing.T) {
	oldArgs := os.Args
	oldStdout := os.Stdout

	// Test too few arguments
	os.Args = []string{"todo"}
	mockExitCalled = false
	mockExitCode = 0
	r, w, _ := os.Pipe()
	os.Stdout = w

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called for too few arguments")
		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	main()
	out, _ := ioutil.ReadAll(r)

	expectedError := `{"error":"invalid arguments"}`
	if strings.TrimSpace(string(out)) != expectedError {
		t.Errorf("expected %s, got %s", expectedError, strings.TrimSpace(string(out)))
	}

	// Test add with missing description
	os.Args = []string{"todo", "add"}
	mockExitCalled = false
	mockExitCode = 0
	r, w, _ = os.Pipe()
	os.Stdout = w

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called for missing description")
		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	main()

out, _ = ioutil.ReadAll(r)

	if strings.TrimSpace(string(out)) != expectedError {
		t.Errorf("expected %s, got %s", expectedError, strings.TrimSpace(string(out)))
	}

	// Test done with missing ID
	os.Args = []string{"todo", "done"}
	mockExitCalled = false
	mockExitCode = 0
	r, w, _ = os.Pipe()
	os.Stdout = w

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called for missing ID")
		}
