		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	// Temporarily set tasksFile to the testTasksFile before calling main
	currentTasksFile = tasksFile
	tasksFile = testTasksFile
	defer func() { tasksFile = currentTasksFile }()
	main()
	out, _ = ioutil.ReadAll(r)

	if strings.TrimSpace(string(out)) != expectedError {
		t.Errorf("expected %s, got %s", expectedError, strings.TrimSpace(string(out)))
	}

	// Test done with missing ID
	os.Args = []string{"todo", "done"}
	mockExitCalled = false
	mockExitCode = 0
	r, w, _ = os.Pipe()
	os.Stdout = w

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called for missing ID")
		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	// Temporarily set tasksFile to the testTasksFile before calling main
	currentTasksFile = tasksFile
	tasksFile = testTasksFile
	defer func() { tasksFile = currentTasksFile }()
	main()
	out, _ = ioutil.ReadAll(r)

	if strings.TrimSpace(string(out)) != expectedError {
		t.Errorf("expected %s, got %s", expectedError, strings.TrimSpace(string(out)))
	}

	// Test done with invalid ID
	os.Args = []string{"todo", "done", "abc"}
	mockExitCalled = false
	mockExitCode = 0
	r, w, _ = os.Pipe()
	os.Stdout = w

	defer func() {
		r := recover()
		if r == nil || r.(string) != "exit called" {
			t.Errorf("expected mockExit to be called for invalid ID")
		}
		if !mockExitCalled || mockExitCode != 42 {
			t.Errorf("expected mockExit to be called with code 42, got %d", mockExitCode)
		}
		w.Close()
		os.Stdout = oldStdout
		os.Args = oldArgs
	}()
	// Temporarily set tasksFile to the testTasksFile before calling main
	currentTasksFile = tasksFile
	tasksFile = testTasksFile
	defer func() { tasksFile = currentTasksFile }()
	main()
	out, _ = ioutil.ReadAll(r)

	expectedErrorInvalidID := `{"error":"invalid arguments: task ID must be an integer"}`
	if strings.TrimSpace(string(out)) != expectedErrorInvalidID {
